def compute(vars):
    costs = {
        2018: vars["v1"],
        2017: vars["v2"],
        2016: vars["v3"],
        2015: vars["v4"],
        2014: vars["v5"],
    }
    year = min(costs, key=costs.get)
    return {
        "value": year,
        "trace": {
            "transaction_based_costs_by_year": costs,
            "least_cost": costs[year],
            "output_meta": {"currency": None, "scale": None, "unit": "year"},
        },
    }
